import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Chrome, UserPlus, ShieldCheck, Globe } from 'lucide-react';

const Home = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const GOOGLE_CLIENT_ID = "";

  // Same background as Intro for consistency
  const bgImage = "https://images.unsplash.com/photo-1497215728101-856f4ea42174?auto=format&fit=crop&q=80&w=2070";

  const handleLogin = (e) => {
    e.preventDefault();
    console.log("Authenticating...");
    navigate('/admin');
  };

  // Google Login
  const handleGoogleLogin = () => {
    window.google.accounts.id.initialize({
      client_id: GOOGLE_CLIENT_ID,
      callback: handleCredentialResponse
    });

    window.google.accounts.id.prompt();
  };

  const handleCredentialResponse = (response) => {
    console.log("Google Token:", response.credential);
    navigate("/admin");
  };

  return (
    <div 
      className="min-h-screen flex flex-col items-center justify-center relative font-sans overflow-hidden"
      style={{ 
        backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.8), rgba(88, 28, 135, 0.7)), url(${bgImage})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center'
      }}
    >

      {/* Decorative Blur Orbs */}
      <div className="absolute -top-24 -left-24 w-96 h-96 bg-purple-500/20 rounded-full blur-3xl"></div>
      <div className="absolute -bottom-24 -right-24 w-96 h-96 bg-blue-500/20 rounded-full blur-3xl"></div>

      {/* Register Button */}
      <div className="absolute top-8 right-8 z-20">
        <button 
          onClick={() => navigate('/register')}
          className="flex items-center gap-2 bg-white/10 backdrop-blur-md text-white border border-white/20 px-6 py-2.5 rounded-full font-bold hover:bg-white hover:text-purple-700 transition-all shadow-xl active:scale-95"
        >
          <UserPlus size={18} />
          Join Us
        </button>
      </div>

      {/* Login Card */}
      <div className="z-10 w-full max-w-md px-4">
        <div className="bg-white/10 backdrop-blur-2xl p-10 rounded-[3rem] shadow-2xl border border-white/20">
          
          {/* Logo */}
          <div className="text-center mb-10">
            <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-tr from-purple-500 to-blue-500 rounded-3xl shadow-lg mb-4 transform -rotate-12 hover:rotate-0 transition-transform duration-300">
              <Globe className="text-white" size={40} />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter">
              Talent <span className="text-purple-400">Pool</span>
            </h1>
            <p className="text-gray-300 text-sm mt-2 font-medium tracking-wide">
              Secure Access Portal
            </p>
          </div>

          {/* Login Form */}
          <form onSubmit={handleLogin} className="space-y-6">

            {/* Email */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-purple-300 uppercase tracking-widest ml-2">
                Email Address
              </label>
              <div className="relative group">
                <Mail className="absolute left-4 top-4 text-gray-400 group-focus-within:text-purple-400 transition-colors" size={20} />
                <input 
                  type="email" 
                  placeholder="admin@talentpool.com"
                  className="w-full pl-12 pr-4 py-4 bg-white/5 border border-white/10 rounded-2xl text-white placeholder-gray-500 focus:ring-2 focus:ring-purple-500 focus:bg-white/10 outline-none transition-all"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Password */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-purple-300 uppercase tracking-widest ml-2">
                Password
              </label>
              <div className="relative group">
                <Lock className="absolute left-4 top-4 text-gray-400 group-focus-within:text-purple-400 transition-colors" size={20} />
                <input 
                  type="password" 
                  placeholder="••••••••"
                  className="w-full pl-12 pr-4 py-4 bg-white/5 border border-white/10 rounded-2xl text-white placeholder-gray-500 focus:ring-2 focus:ring-purple-500 focus:bg-white/10 outline-none transition-all"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            {/* Sign In Button */}
            <button 
              type="submit"
              className="w-full bg-gradient-to-r from-[#7c5dfa] to-[#5a3dfa] hover:from-[#6a4dec] hover:to-[#4a2dec] text-white font-black py-4 rounded-2xl shadow-xl shadow-purple-900/20 transition-all transform active:scale-[0.97] tracking-widest"
            >
              SIGN IN
            </button>

          </form>

          {/* Divider */}
          <div className="flex items-center my-8">
            <div className="flex-grow border-t border-white/10"></div>
            <span className="px-4 text-gray-500 text-[10px] font-black uppercase tracking-[0.2em]">
              Verified Access Only
            </span>
            <div className="flex-grow border-t border-white/10"></div>
          </div>

          {/* Google Login Button */}
          <button 
            type="button"
            onClick={handleGoogleLogin}
            className="w-full flex items-center justify-center gap-3 border border-white/10 py-4 rounded-2xl hover:bg-white/5 transition-all text-white font-bold bg-white/5 shadow-sm"
          >
            <Chrome size={20} className="text-red-400" />
            Continue with Google
          </button>

        </div>
      </div>

      {/* Security Badge */}
      <div className="mt-8 flex items-center gap-2 text-gray-400 text-xs font-bold uppercase tracking-widest opacity-60">
        <ShieldCheck size={14} />
        End-to-End Encrypted Verification
      </div>

    </div>
  );
};

export default Home;
